// Generic "first true" search over integers in (lo, hi]; ok must be monotonic F...FT...T
function firstTrue(lo, hi, ok) {
  while (hi - lo > 1) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (ok(mid)) hi = mid; else lo = mid;
  }
  return hi;
}

// Koko eating bananas
function minEatingSpeed(piles, h) {
  const hours = (k) => piles.reduce((s, p) => s + Math.ceil(p / k), 0);
  return firstTrue(0, Math.max(...piles), (k) => hours(k) <= h);
}

// Lower bound on a sorted array
const lowerBound = (a, x) => firstTrue(-1, a.length, (i) => i === a.length || a[i] >= x);

// Ship packages within D days
function shipWithinDays(weights, days) {
  const daysNeeded = (cap) => { let d = 1, cur = 0; for (const w of weights) { if (cur + w > cap) { d++; cur = 0; } cur += w; } return d; };
  return firstTrue(Math.max(...weights) - 1, weights.reduce((a, b) => a + b, 0), (cap) => daysNeeded(cap) <= days);
}

// Search in rotated sorted array (distinct values)
function searchRotated(a, target) {
  let lo = 0, hi = a.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (a[mid] === target) return mid;
    if (a[lo] <= a[mid]) {                       // left half sorted
      if (a[lo] <= target && target < a[mid]) hi = mid - 1; else lo = mid + 1;
    } else {                                     // right half sorted
      if (a[mid] < target && target <= a[hi]) lo = mid + 1; else hi = mid - 1;
    }
  }
  return -1;
}

