def first_true(lo, hi, ok):
    """Smallest x in (lo, hi] with ok(x) true; ok is monotonic False...True."""
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if ok(mid): hi = mid
        else: lo = mid
    return hi

def min_eating_speed(piles, h):
    return first_true(0, max(piles), lambda k: sum(math.ceil(p / k) for p in piles) <= h)

def split_array_largest_sum(nums, m):
    def parts_needed(limit):
        parts, cur = 1, 0
        for x in nums:
            if cur + x > limit: parts, cur = parts + 1, 0
            cur += x
        return parts
    return first_true(max(nums) - 1, sum(nums), lambda lim: parts_needed(lim) <= m)

