// Minimal binary min-heap with a comparator (JS has no built-in)
class Heap {
  constructor(cmp = (a, b) => a - b) { this.a = []; this.cmp = cmp; }
  get size() { return this.a.length; }
  peek() { return this.a[0]; }
  push(x) {
    const a = this.a; a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.cmp(a[i], a[p]) >= 0) break;
      [a[i], a[p]] = [a[p], a[i]]; i = p;
    }
  }
  pop() {
    const a = this.a, top = a[0], last = a.pop();
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1; let m = i;
        if (l < a.length && this.cmp(a[l], a[m]) < 0) m = l;
        if (r < a.length && this.cmp(a[r], a[m]) < 0) m = r;
        if (m === i) break;
        [a[i], a[m]] = [a[m], a[i]]; i = m;
      }
    }
    return top;
  }
}

// kth largest in a stream: min-heap of size k
class KthLargest {
  constructor(k, nums) { this.k = k; this.h = new Heap(); nums.forEach((x) => this.add(x)); }
  add(x) { this.h.push(x); if (this.h.size > this.k) this.h.pop(); return this.h.peek(); }
}

// Running median with two heaps
class MedianFinder {
  constructor() { this.lo = new Heap((a, b) => b - a); this.hi = new Heap(); } // lo = max-heap
  add(x) {
    this.lo.push(x); this.hi.push(this.lo.pop());
    if (this.hi.size > this.lo.size) this.lo.push(this.hi.pop());
  }
  median() { return this.lo.size > this.hi.size ? this.lo.peek() : (this.lo.peek() + this.hi.peek()) / 2; }
}

import heapq
from collections import Counter

def kth_largest(nums, k):
    h = nums[:k]; heapq.heapify(h)                   # min-heap of the k largest so far
    for x in nums[k:]:
        if x > h[0]: heapq.heapreplace(h, x)         # pop smallest and push x in one step
    return h[0]

def top_k_frequent(nums, k):
    return [x for x, _ in Counter(nums).most_common(k)]      # uses a heap internally, O(n log k)

def merge_k_sorted(lists):
    heap = [(l[0], i, 0) for i, l in enumerate(lists) if l]
    heapq.heapify(heap)
    out = []
    while heap:
        val, i, j = heapq.heappop(heap)
        out.append(val)
        if j + 1 < len(lists[i]):
            heapq.heappush(heap, (lists[i][j + 1], i, j + 1))
    return out

def min_meeting_rooms(intervals):
    ends = []                                        # min-heap of end times of rooms in use
    for start, end in sorted(intervals):
        if ends and ends[0] <= start: heapq.heapreplace(ends, end)   # reuse the earliest-free room
        else: heapq.heappush(ends, end)
    return len(ends)

class MedianFinder:
    def __init__(self): self.lo, self.hi = [], []            # lo: max-heap via negation; hi: min-heap
    def add(self, x):
        heapq.heappush(self.lo, -x)
        heapq.heappush(self.hi, -heapq.heappop(self.lo))
        if len(self.hi) > len(self.lo): heapq.heappush(self.lo, -heapq.heappop(self.hi))
    def median(self):
        return -self.lo[0] if len(self.lo) > len(self.hi) else (-self.lo[0] + self.hi[0]) / 2

// Top-k frequent with a min-heap of size k
int[] topKFrequent(int[] nums, int k) {
    Map<Integer, Integer> freq = new HashMap<>();
    for (int x : nums) freq.merge(x, 1, Integer::sum);
    PriorityQueue<Map.Entry<Integer, Integer>> pq = new PriorityQueue<>(Map.Entry.comparingByValue());
    for (var e : freq.entrySet()) { pq.offer(e); if (pq.size() > k) pq.poll(); }
    int[] out = new int[k];
    for (int i = k - 1; i >= 0; i--) out[i] = pq.poll().getKey();
    return out;
}

class MedianFinder {
    private final PriorityQueue<Integer> lo = new PriorityQueue<>(Collections.reverseOrder()); // max-heap
    private final PriorityQueue<Integer> hi = new PriorityQueue<>();                           // min-heap
    void addNum(int x) {
        lo.offer(x); hi.offer(lo.poll());
        if (hi.size() > lo.size()) lo.offer(hi.poll());
    }
    double findMedian() { return lo.size() > hi.size() ? lo.peek() : (lo.peek() + hi.peek()) / 2.0; }
}

// priority_queue is a MAX-heap by default
int findKthLargest(vector<int>& nums, int k) {
    priority_queue<int, vector<int>, greater<int>> pq;       // min-heap of size k
    for (int x : nums) { pq.push(x); if ((int)pq.size() > k) pq.pop(); }
    return pq.top();
}

class MedianFinder {
