    priority_queue<int, vector<int>, greater<int>> hi;       // min-heap
public:
    void addNum(int x) {
        lo.push(x); hi.push(lo.top()); lo.pop();
        if (hi.size() > lo.size()) { lo.push(hi.top()); hi.pop(); }
    }
    double findMedian() { return lo.size() > hi.size() ? lo.top() : (lo.top() + hi.top()) / 2.0; }
};

const DIRS = [[1, 0], [-1, 0], [0, 1], [0, -1]];

// Number of Islands: iterative DFS, mark visited by mutating a copy-friendly set
function numIslands(grid) {
  const m = grid.length, n = grid[0].length, seen = Array.from({ length: m }, () => new Array(n).fill(false));
  let count = 0;
  for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) {
    if (grid[r][c] !== "1" || seen[r][c]) continue;
    count++;
    const stack = [[r, c]]; seen[r][c] = true;           // mark when pushing
    while (stack.length) {
      const [x, y] = stack.pop();
      for (const [dx, dy] of DIRS) {
        const nx = x + dx, ny = y + dy;
        if (nx >= 0 && ny >= 0 && nx < m && ny < n && grid[nx][ny] === "1" && !seen[nx][ny]) {
          seen[nx][ny] = true; stack.push([nx, ny]);
        }
      }
    }
  }
  return count;
}

// Rotting Oranges: multi-source BFS by levels
function orangesRotting(grid) {
  const m = grid.length, n = grid[0].length; let fresh = 0, q = [];
  for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) {
    if (grid[r][c] === 2) q.push([r, c]); else if (grid[r][c] === 1) fresh++;
  }
  let minutes = 0;
  while (q.length && fresh > 0) {
    const next = [];
    for (const [r, c] of q) for (const [dr, dc] of DIRS) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nc >= 0 && nr < m && nc < n && grid[nr][nc] === 1) { grid[nr][nc] = 2; fresh--; next.push([nr, nc]); }
    }
    q = next; minutes++;
  }
  return fresh === 0 ? minutes : -1;
}

from collections import deque

DIRS = ((1, 0), (-1, 0), (0, 1), (0, -1))

def num_islands(grid):
    m, n = len(grid), len(grid[0])
    seen, count = set(), 0
    for r in range(m):
        for c in range(n):
            if grid[r][c] != "1" or (r, c) in seen: continue
            count += 1
            stack = [(r, c)]; seen.add((r, c))
            while stack:
                x, y = stack.pop()
                for dx, dy in DIRS:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == "1" and (nx, ny) not in seen:
                        seen.add((nx, ny)); stack.append((nx, ny))
    return count

def oranges_rotting(grid):
    m, n = len(grid), len(grid[0])
    q = deque((r, c) for r in range(m) for c in range(n) if grid[r][c] == 2)
    fresh = sum(row.count(1) for row in grid)
    minutes = 0
    while q and fresh:
        for _ in range(len(q)):                      # one minute = one BFS level
            r, c = q.popleft()
            for dr, dc in DIRS:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 1:
                    grid[nr][nc] = 2; fresh -= 1; q.append((nr, nc))
        minutes += 1
    return minutes if fresh == 0 else -1

def can_finish(num_courses, prereqs):                # cycle detection via Kahn's algorithm
    adj = [[] for _ in range(num_courses)]; indeg = [0] * num_courses
    for a, b in prereqs: adj[b].append(a); indeg[a] += 1
    q = deque(i for i, d in enumerate(indeg) if d == 0); done = 0
    while q:
        u = q.popleft(); done += 1
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0: q.append(v)
    return done == num_courses

def is_bipartite(graph):
    color = {}
    for s in range(len(graph)):
        if s in color: continue
        color[s] = 0; q = deque([s])
        while q:
            u = q.popleft()
            for v in graph[u]:
                if v not in color: color[v] = 1 - color[u]; q.append(v)
                elif color[v] == color[u]: return False
    return True

int[][] DIRS = {{1,0},{-1,0},{0,1},{0,-1}};

int orangesRotting(int[][] g) {
    int m = g.length, n = g[0].length, fresh = 0, minutes = 0;
    Deque<int[]> q = new ArrayDeque<>();
    for (int r = 0; r < m; r++) for (int c = 0; c < n; c++) {
        if (g[r][c] == 2) q.add(new int[]{r, c}); else if (g[r][c] == 1) fresh++;
    }
    while (!q.isEmpty() && fresh > 0) {
        for (int i = q.size(); i > 0; i--) {
            int[] cur = q.poll();
            for (int[] d : DIRS) {
                int nr = cur[0] + d[0], nc = cur[1] + d[1];
                if (nr >= 0 && nc >= 0 && nr < m && nc < n && g[nr][nc] == 1) { g[nr][nc] = 2; fresh--; q.add(new int[]{nr, nc}); }
            }
        }
        minutes++;
    }
    return fresh == 0 ? minutes : -1;
}

int numIslands(vector<vector<char>>& g) {
    int m = g.size(), n = g[0].size(), cnt = 0;
    int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
    for (int r = 0; r < m; r++) for (int c = 0; c < n; c++) {
        if (g[r][c] != '1') continue;
        cnt++;
        queue<pair<int,int>> q; q.push({r, c}); g[r][c] = '0';   // mark when enqueuing (mutates input)
        while (!q.empty()) {
            auto [x, y] = q.front(); q.pop();
            for (int k = 0; k < 4; k++) {
                int nx = x + dr[k], ny = y + dc[k];
                if (nx >= 0 && ny >= 0 && nx < m && ny < n && g[nx][ny] == '1') { g[nx][ny] = '0'; q.push({nx, ny}); }
            }
        }
    }
    return cnt;
}
